<header class="top"><b>${BRAND_MARK}${esc(cfg.business_name || 'Tussock Ridge Farming Ltd')}</b><span>${esc(opts.tag || 'Secure link')}</span></header>
<main class="card${opts.wide ? ' wide' : ''}">${body}</main>
<div class="foot">Demo by Forrof. All people, businesses and numbers are fictional.</div></body></html>`;
};

// How the agent reads a consent, certificate or other record that expires. Injected into the nodes that watch or show the register.
//
// Consents follow the renewal rule in section 124 of the Resource Management Act: lodge a renewal at least 6 months before
// expiry and you may keep operating until the council decides; lodge 3 to 6 months before and the council decides whether you
// may; lodge later and you must stop when the consent expires. The months are settings because the rules are being changed.
// Certificates, vehicle fitness and insurance use simple 30-day and 7-day warnings.
const REG_RANK = { expired: 0, late: 1, urgent: 2, missing: 3, lodge: 4, soon: 5, plan: 6, lodged: 7, ok: 8 };
// How many days to leave between reminders to the person responsible, by state.
const REG_CADENCE = { expired: 7, missing: 7, urgent: 3, soon: 14, late: 3, lodge: 7, plan: 30 };
const regNeedsAction = (state) => ['expired', 'late', 'urgent', 'missing', 'lodge', 'soon', 'plan'].includes(state);

// What to tell the person who holds the record. The "do not assign" prompt is for the manager, not for them.
const selfText = (r, st) => {
  if (r.kind === 'Consent') return st.detail;
  const what = r.type.toLowerCase();
  if (st.state === 'expired') return `Your ${what} expired ${-st.left} day${st.left === -1 ? '' : 's'} ago (${fmtDate(r.expiry_date)}).`;
  if (st.state === 'missing') return `We have no record of your ${what} on file.`;
  if (r.expiry_date) return `Your ${what} expires on ${fmtDate(r.expiry_date)} (${st.left} day${st.left === 1 ? '' : 's'}).`;
  return st.detail;
};

const registerState = (r, cfg, today) => {
  const restriction = r.restriction || '';
  const stop = restriction ? ` Do not assign ${restriction} until it is sorted.` : '';
  if (r.status === 'missing' && !r.expiry_date) {
    return { state: 'missing', tone: 'warn', label: 'No evidence on file', detail: `Nothing on file yet.${stop}`, left: null };
  }
  const exp = r.expiry_date;
  if (!exp) return { state: 'ok', tone: 'ok', label: 'Current', detail: 'No expiry date.', left: null };
  const left = daysBetween(today, exp);
  const soonDays = Number(cfg.cert_soon_days || 30);
  const urgentDays = Number(cfg.cert_urgent_days || 7);

  if (r.kind === 'Consent') {
    const lodgeBy = addMonths(exp, -Number(cfg.consent_lodge_months || 6));
    const cutoff = addMonths(exp, -Number(cfg.consent_cutoff_months || 3));
    const planFrom = addMonths(exp, -Number(cfg.consent_plan_months || 8));
    if (r.renewal_lodged_at) {
      const when = String(r.renewal_lodged_at).slice(0, 10);
      const rule = when <= lodgeBy ? 'at least 6 months before it expires, so you may keep operating until the council decides'
        : when <= cutoff ? 'between 3 and 6 months before it expires, so keeping on operating is at the council\'s discretion: get its agreement in writing'
          : 'less than 3 months before it expires, so you must stop when it expires unless it is decided first';
      if (left < 0 && when > lodgeBy) return { state: 'expired', tone: 'bad', label: 'Expired', detail: `Expired ${-left} days ago (${fmtDate(exp)}). The renewal was lodged ${fmtDate(when)}, ${rule}.${stop}`, left };
      return { state: 'lodged', tone: 'info', label: 'Renewal lodged', detail: `Renewal lodged ${fmtDate(when)}, ${rule}.`, left };
    }
    if (left < 0) return { state: 'expired', tone: 'bad', label: 'Expired', detail: `Expired ${-left} days ago (${fmtDate(exp)}).${stop}`, left };
    if (today > cutoff) return { state: 'late', tone: 'bad', label: 'Past the cut-off', detail: `Less than ${cfg.consent_cutoff_months || 3} months left and no renewal lodged. Unless it is renewed first, you must stop ${restriction || 'the activity'} when it expires on ${fmtDate(exp)}. Call your consultant today.`, left };
    if (today > lodgeBy) return { state: 'lodge', tone: 'warn', label: 'Lodge the renewal now', detail: `The ${cfg.consent_lodge_months || 6}-month date (${fmtDate(lodgeBy)}) has passed, so the council now decides whether you may keep operating while it processes a renewal. Lodge by ${fmtDate(cutoff)} at the latest.`, left };
    if (today >= planFrom) return { state: 'plan', tone: 'warn', label: 'Plan the renewal', detail: `Lodge the renewal by ${fmtDate(lodgeBy)} (${cfg.consent_lodge_months || 6} months before expiry) to keep operating as of right while the council decides.`, left };
    return { state: 'ok', tone: 'ok', label: 'Current', detail: `Expires ${fmtDate(exp)}. Lodge a renewal by ${fmtDate(lodgeBy)}.`, left };
  }

  if (left < 0) return { state: 'expired', tone: 'bad', label: 'Expired', detail: `Expired ${-left} days ago (${fmtDate(exp)}).${stop}`, left };
  if (left <= urgentDays) return { state: 'urgent', tone: 'bad', label: `Expires in ${left} day${left === 1 ? '' : 's'}`, detail: `Expires ${fmtDate(exp)}.`, left };
  if (left <= soonDays) return { state: 'soon', tone: 'warn', label: `Expires in ${left} days`, detail: `Expires ${fmtDate(exp)}.`, left };
  return { state: 'ok', tone: 'ok', label: 'Current', detail: `Expires ${fmtDate(exp)}.`, left };
};

// GET /webhook/register/upload?t=TOKEN: the person responsible uploads a renewed certificate or consent from their phone.
const cfg = configFrom();
const token = String($('Person opens upload link').first().json.query?.t || '');
const r = tableRows('Register').find((x) => token && x.upload_token === token);
if (!r) return [{ json: { html: page('Link not found', `<h1>This upload link has expired</h1><p class="muted">Please contact ${esc(cfg.admin_name)} at ${esc(cfg.business_name)}.</p>`) } }];
if (r.status === 'received') {
  return [{ json: { html: page('Received', `<h1>Thanks, ${esc(firstName(r.responsible_name))}</h1>${callout('ok', `We have your ${esc(r.type.toLowerCase())}. ${esc(cfg.admin_name)} is checking it.`)}`) } }];
}
const st = registerState(r, cfg, nzToday());
const body = `<h1>${esc(r.type)}</h1>
<p>Kia ora ${esc(firstName(r.responsible_name))}. ${esc(selfText(r, st))} Upload the ${r.kind === 'Consent' ? 'renewed consent' : 'new certificate'} here. It goes to ${esc(cfg.admin_name)} to check.</p>
${r.note ? callout('warn', `<b>Please upload it again.</b> ${esc(r.note)}`) : ''}
<form method="post" action="${cfg.base_url}/webhook/register/upload" enctype="multipart/form-data">
<input type="hidden" name="t" value="${esc(token)}">
<label for="file">Document (PDF or photo, up to 10 MB)</label><input id="file" name="file" type="file" accept="image/*,application/pdf" required>
<label for="expiry">New expiry date</label><input id="expiry" name="expiry" type="date" required>
<button class="btn" type="submit">Upload securely</button></form>
<p class="muted">Only ${esc(cfg.business_name)} can see your document. There is no login.</p>`;
return [{ json: { html: page(`Upload: ${r.type}`, body) } }];

// Shared helpers injected at the top of every Code node by scripts/build-workflows.mjs.
const TZ = 'Pacific/Auckland';
const DAY_MS = 86400000;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const round2 = (n) => Math.round(Number((Number(n || 0) * 100).toFixed(6))) / 100;
const money = (n) => new Intl.NumberFormat('en-NZ', { style: 'currency', currency: 'NZD' }).format(Number(n || 0));
const priceText = (n) => '$' + Number(n || 0).toLocaleString('en-NZ', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
const qtyText = (n) => Number(n || 0).toLocaleString('en-NZ', { maximumFractionDigits: 2 });
const unitText = (qty, unit) => (Number(qty) !== 1 && { load: 'loads', bale: 'bales' }[unit]) || unit;
const newToken = () => require('crypto').randomBytes(18).toString('hex');
// Each call is one millisecond later than the last, so rows written in one run keep their order.
let _seq = 0;
const nowIso = () => new Date(Date.now() + _seq++).toISOString();

// Calendar dates are plain "YYYY-MM-DD" strings in New Zealand time, so this PC's own clock never matters.
const nzToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const dateOf = (s) => new Date(`${String(s).slice(0, 10)}T00:00:00Z`);
const isoDay = (d) => d.toISOString().slice(0, 10);
const addDays = (s, n) => isoDay(new Date(dateOf(s).getTime() + n * DAY_MS));
const addMonths = (s, n) => {
  const d = dateOf(s);
  const day = d.getUTCDate();
  const target = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n, 1));
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate();
  target.setUTCDate(Math.min(day, last));
  return isoDay(target);
};
const daysBetween = (from, to) => Math.round((dateOf(to) - dateOf(from)) / DAY_MS);
const fmtDate = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' }) : '—');
const fmtLong = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '—');
const fmtTime = (iso) => (iso ? new Date(iso).toLocaleString('en-NZ', { timeZone: TZ, day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true }) : '');
const ago = (iso) => {
  if (!iso) return '';
  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return `${Math.round(s / 86400)} d ago`;
};

// Every Code node runs right after "Load data", whose single item holds one array per data table.
const DATA = $input.first().json || {};
const tableRows = (table) => (Array.isArray(DATA[table]) ? DATA[table] : []);
const configFrom = () => Object.fromEntries(tableRows('Config').map((r) => [r.key, r.value]));
const firstName = (name) => String(name || '').split(' ')[0];
const person = (cfg, role) => ({ name: cfg[`${role}_name`] || '', email: cfg[`${role}_email`] || '', phone: cfg[`${role}_phone`] || '' });

// A message for the Shared · Send message workflow. Nothing is sent from anywhere else.
const msg = (m) => ({
  channel: m.channel, to_name: m.to_name || '', to_address: m.to_address || '', subject: m.subject || '',
  body: m.body || '', link: m.link || '', related: m.related || '', workflow: m.workflow || '',
});
// Text the phone if we have one, otherwise email. `both` sends the email as well.
const reach = (p, m, how = 'auto') => {
  const out = [];
  const to = { to_name: p.name, related: m.related, workflow: m.workflow };
  if (p.phone && how !== 'email') out.push(msg({ ...to, channel: 'SMS', to_address: p.phone, body: m.sms || m.body, link: m.link }));
  if (p.email && (how === 'email' || how === 'both' || !p.phone)) out.push(msg({ ...to, channel: 'Email', to_address: p.email, subject: m.subject, body: m.body, link: m.link }));
  return out;
};
// One line of the audit trail: who did what, to what, and when.
const auditRow = (actor, type, flow, subject, action, detail = '') => ({
  at: nowIso(), actor, actor_type: type, flow, subject: String(subject).slice(0, 200), action: String(action).slice(0, 200), detail: String(detail).slice(0, 700),
});
// The page a webhook link returns after a person acts: back to the console, on the same tab, with a notice.
const backToConsole = (cfg, tab, notice) => `${cfg.base_url}/webhook/console?tab=${encodeURIComponent(tab || 'gate')}&done=${encodeURIComponent(notice)}`;

const pill = (tone, text) => `<span class="pill ${tone}">${esc(text)}</span>`;
const callout = (tone, html) => `<div class="callout ${tone}">${html}</div>`;

